import os
import hmac
import hashlib
import time
import json
import secrets
import tempfile
from pathlib import Path
from typing import Optional, Tuple

# Configuration
SESSION_DIR = "/var/lib/app/sessions"
SESSION_SECRET = os.environ.get("SESSION_SECRET", secrets.token_hex(32))
MAX_SESSION_AGE = 3600  # 1 hour


def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Timing-safe comparison to prevent timing attacks."""
    return hmac.compare_digest(a, b)


def compute_session_mac(session_id: str, data: bytes) -> str:
    """Compute HMAC-SHA256 for session integrity verification."""
    mac = hmac.new(
        SESSION_SECRET.encode('utf-8'),
        msg=f"{session_id}:{data.hex()}".encode('utf-8'),
        digestmod=hashlib.sha256
    )
    return mac.hexdigest()


def _validate_session_id(session_id: str) -> bool:
    """Validate session ID format - alphanumeric only, fixed length."""
    if not session_id or len(session_id) != 64:
        return False
    return all(c in '0123456789abcdef' for c in session_id)


def _get_session_path(session_id: str) -> str:
    """Construct session file path with directory traversal prevention."""
    if not _validate_session_id(session_id):
        raise ValueError("Invalid session ID format")
    # Use only the validated hex string - no path components possible
    return os.path.join(SESSION_DIR, f"sess_{session_id}")


def _safe_file_read(filepath: str) -> Optional[bytes]:
    """Read file contents safely.

    Uses validated path from _get_session_path which ensures
    the filename is a fixed-format hex string with no path separators.
    """
    try:
        # Verify the file exists and is a regular file
        stat_result = os.stat(filepath)
        if not os.path.isfile(filepath):
            return None
        # Check file permissions are restrictive
        if stat_result.st_mode & 0o077:
            return None
        # Read the validated file
        fd = os.open(filepath, os.O_RDONLY)
        try:
            data = os.read(fd, 8192)
            return data
        finally:
            os.close(fd)
    except (OSError, IOError):
        return None


def _safe_file_write(filepath: str, data: bytes) -> bool:
    """Write file contents atomically."""
    tmp_path = filepath + f".tmp.{os.getpid()}"
    try:
        fd = os.open(tmp_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            os.write(fd, data)
        finally:
            os.close(fd)
        os.rename(tmp_path, filepath)
        return True
    except (OSError, IOError):
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        return False


class SessionManager:
    """Secure file-based session manager with HMAC integrity checks."""

    def __init__(self, session_dir: str = SESSION_DIR):
        self._session_dir = session_dir
        os.makedirs(session_dir, mode=0o700, exist_ok=True)

    def create_session(self, user_id: str, metadata: dict) -> Optional[str]:
        """Create a new session and return the session ID."""
        session_id = secrets.token_hex(32)
        session_data = {
            "user_id": user_id,
            "created_at": time.time(),
            "metadata": metadata
        }
        payload = json.dumps(session_data).encode('utf-8')
        mac = compute_session_mac(session_id, payload)

        # Store MAC + payload
        file_content = f"{mac}\n".encode('utf-8') + payload
        filepath = _get_session_path(session_id)

        if _safe_file_write(filepath, file_content):
            return session_id
        return None

    def validate_session(self, session_id: str) -> Tuple[bool, Optional[dict]]:
        """Validate a session and return its data if valid.

        Security checks performed:
        1. Session ID format validation (hex, fixed length)
        2. File existence and type verification
        3. File permission check (no world/group access)
        4. HMAC integrity verification (constant-time)
        5. Session expiry check
        """
        if not _validate_session_id(session_id):
            return False, None

        filepath = _get_session_path(session_id)

        # Read session file
        raw_data = _safe_file_read(filepath)
        if raw_data is None:
            return False, None

        # Parse MAC and payload
        try:
            newline_idx = raw_data.index(b'\n')
            stored_mac = raw_data[:newline_idx].decode('utf-8')
            payload = raw_data[newline_idx + 1:]
        except (ValueError, UnicodeDecodeError):
            return False, None

        # Verify HMAC integrity
        expected_mac = compute_session_mac(session_id, payload)
        if not constant_time_compare(
            stored_mac.encode('utf-8'),
            expected_mac.encode('utf-8')
        ):
            return False, None

        # Parse and validate session data
        try:
            session_data = json.loads(payload)
        except json.JSONDecodeError:
            return False, None

        # Check session age
        created_at = session_data.get("created_at", 0)
        if time.time() - created_at > MAX_SESSION_AGE:
            self.destroy_session(session_id)
            return False, None

        return True, session_data

    def destroy_session(self, session_id: str) -> bool:
        """Securely destroy a session."""
        if not _validate_session_id(session_id):
            return False
        filepath = _get_session_path(session_id)
        try:
            os.unlink(filepath)
            return True
        except OSError:
            return False


# HTTP request handler (simplified WSGI-like interface)
def handle_request(environ: dict) -> Tuple[int, dict, str]:
    """Handle incoming HTTP request with session validation."""
    path = environ.get("PATH_INFO", "/")
    method = environ.get("REQUEST_METHOD", "GET")

    manager = SessionManager()

    if path == "/api/session" and method == "POST":
        # Create session
        body = environ.get("wsgi.input", b"{}")
        try:
            request_data = json.loads(body)
        except json.JSONDecodeError:
            return 400, {}, '{"error": "invalid json"}'

        user_id = request_data.get("user_id", "")
        if not user_id or not user_id.isalnum():
            return 400, {}, '{"error": "invalid user_id"}'

        session_id = manager.create_session(user_id, request_data.get("meta", {}))
        if session_id:
            return 201, {"Set-Cookie": f"sid={session_id}; HttpOnly; Secure; SameSite=Strict"}, json.dumps({"session_id": session_id})
        return 500, {}, '{"error": "session creation failed"}'

    elif path == "/api/profile" and method == "GET":
        # Validate session and return profile
        cookie_header = environ.get("HTTP_COOKIE", "")
        session_id = _extract_session_from_cookie(cookie_header)
        if not session_id:
            return 401, {}, '{"error": "no session"}'

        valid, session_data = manager.validate_session(session_id)
        if not valid:
            return 401, {}, '{"error": "invalid session"}'

        return 200, {}, json.dumps({"user_id": session_data["user_id"], "metadata": session_data["metadata"]})

    return 404, {}, '{"error": "not found"}'


def _extract_session_from_cookie(cookie_header: str) -> Optional[str]:
    """Extract session ID from cookie header."""
    for part in cookie_header.split(";"):
        part = part.strip()
        if part.startswith("sid="):
            return part[4:]
    return None
